package android.os;public final class SystemClock{public static volatile long now=100000;private static volatile boolean real;private static long base,start;public static long elapsedRealtime(){return real?base+(System.nanoTime()-start)/1000000:now;}public static void advance(long value){now+=value;}public static synchronized void startReal(){base=now;start=System.nanoTime();real=true;}public static synchronized void stopReal(){now=elapsedRealtime();real=false;}}
